root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign16-first-norm-check';draft=root/'research/nine-sharing-sign16-first-norm-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='0b8ba7eb4098b2af1d4d0b5c200c8379fdfadf23dfb7227b0068cb1bea9f6da6' and sha(m)=='43cfb72fe36f7c6d77a05b070a170a0099ce029bc804b4743cb46980251d25b9';row,=json.loads(m.read_text())['rows'];name='Sign16FirstNorm';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='bdd62bd007267e438a34baacd4f5605951bd5532a42e860f5fbd4879863e2706' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign16InnerFromSeed','DiophantineConsistency.Sign16OtherRows','DiophantineConsistency.Sign16MoreSharedValues'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('theorem first_of_seed','(hp0 :','(hp1 :','(hp2 :','(hp3 :','(hb : 0 < beta) (hMC : MC < beta) (hMF : MF < 2 * beta)','(hz : InternalZero (seed p) v)','let tau := E beta v * (v 10 + 1) + k - r','Sign16ScalarWindow.q_bound_of_seed','Sign16RankValue.rank_eval','Sign16OtherRows.row01_of_seed','Sign16OtherRows.row02_of_seed','Sign16MoreSharedValues.ey_k_eval'):assert t in s
r=run.read_text();survey=p/'provider-survey.py';assert sha(survey)=='1b03a6e6e6f84f0d35aca8dce643f51a091992488da6af8f8e6ee6bd8b525d14' and "survey['producers']['row' if local=='Sign16OtherRows' else 'more']" in r and "'-M2800'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
for label,pin in [('inner-from-seed','1d32691192c25314dad6fec4a2255533f7e119e4998328b7a8b793417d4ebbc4'),('other-rows','42ca8a3845f213546dae9ef997cd401de3bfce072176c9b639db4de04dd30bcb'),('more-shared-values','9249cd245922d9d101bbfc585e6efe52adb602fa9477e56dce2c129ab90a142d')]:
 check=root/('reviews/nine-sharing-sign16-'+label+'-terminal-independent/check.py');assert sha(check)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
x=subprocess.run([sys.executable,'-I','-S','-B',str(run),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','runner_sha256':sha(run),'scope':'conditional first norm from seed zero and explicit positive beta/port bounds; no V lift'},indent=2,sort_keys=True))
